;; has a cloud (NZ). C: the VSYNC is on - no time.
dw_char
dw_m
    ld bc,0              ; (self-modified: its place in the maps)
    add hl,bc
    ld a,(hl)
    dec hl
    dec hl
    and (hl)             ; (left of the first: the byte before the map - the last has none,
    cp hi(sky_pairs)&#C0 ; written again at worst; the plain sky's tiles in bank 7)
    jr c,dw_cloud
    xor a                ; (Z: none, NC)
    ret
dw_cloud
    inc hl
    ld c,(hl)
    inc hl
    ld b,(hl)
    ld (dw_t+1),bc       ; its tile
    ld hl,(ring_w0)      ; its character in the ring
    ld a,(dw_j+1)
    add a,e
    add a,l
    ld l,a
    jr nc,$+3
    inc h
    ld a,h
    and hi(RING_WORDS-1)
    ld h,a
    add hl,hl
    ld a,h
    or hi(RING_BASE)
    ld h,a
    ld de,#800
dw_half
    ld b,#F5             ; the VSYNC: the flip's interrupt next
    in a,(c)
    rra
    ret c
    di
    ld (dw_sp+1),sp
dw_t
    ld sp,0              ; (self-modified: the tile's next four lines)
    pop bc
    ld (hl),c
    inc l
    ld (hl),b
    add hl,de
    pop bc
    ld (hl),b
    dec l
    ld (hl),c
    add hl,de
    pop bc
    ld (hl),c
    inc l
    ld (hl),b
    add hl,de
    pop bc
    ld (hl),b
    dec l
    ld (hl),c
    add hl,de
    ld (dw_t+1),sp
dw_sp
    ld sp,0              ; (self-modified)
    ei
    bit 7,h              ; (line 4: #6x, past line 7: #8x)
    jr z,dw_half
    or 1                 ; (NZ: written, NC)
    ret
    ASSERT hi(RING_BASE) == #40
